import numpy as np
import time
from itertools import combinations

def construct():
    N = 17
    MIN_DIST = 6
    start_time = time.time()
    time_limit = 55
    
    # 1. Generate the Base Code C_17,8,6
    # This is the even-weight subcode of the [17,9,5] QR code.
    # The [17,9,5] code is the dual of the [17,8,5] QR code.
    
    # Quadratic residues mod 17 (excluding 0)
    residues = {1, 2, 4, 8, 9, 13, 15, 16}
    
    # Generate the [17,8,5] QR code
    # The code is generated by the cyclic shifts of the vector u
    # u[i] = 1 if i in residues else 0
    u = [0] * N
    for i in range(N):
        if i in residues:
            u[i] = 1
            
    # The generator matrix is the circulant matrix of u.
    # We need a basis of dimension 8.
    # The rows of the circulant matrix are linearly dependent.
    # We can take the first 8 rows as a basis?
    # Let's verify rank.
    # For p=17, the QR code has dimension 8.
    # The circulant matrix is 17x17.
    # We can just generate the code by taking all linear combinations of the 8 basis vectors.
    # Which 8 vectors?
    # The standard basis for the cyclic code is the first k rows of the generator matrix, 
    # provided they are independent.
    # Let's extract the first 8 rows of the circulant matrix.
    
    basis_85 = []
    for i in range(8):
        row = [0] * N
        for j in range(N):
            # Circulant shift: row i is u shifted by i
            # u[j-i] ?
            # Standard circulant: C[i,j] = u[(j-i) % N]
            row[j] = u[(j - i) % N]
        basis_85.append(row)
        
    # Generate all 256 codewords of C_17,8,5
    codewords_85 = []
    for mask in range(1 << 8):
        cw = [0] * N
        for i in range(8):
            if (mask >> i) & 1:
                for j in range(N):
                    cw[j] ^= basis_85[i][j]
        codewords_85.append(cw)
        
    # Now find the dual C_17,9,5
    # The dual is the null space of the 8x17 matrix formed by basis_85.
    # We perform Gaussian elimination on the 8x17 matrix over GF(2).
    
    # Matrix A: 8 rows, 17 cols
    A = [row[:] for row in basis_85]
    
    # Reduce to row echelon form
    rank = 0
    for col in range(N):
        # Find pivot
        pivot = -1
        for row in range(rank, 8):
            if A[row][col] == 1:
                pivot = row
                break
        if pivot == -1:
            continue
            
        # Swap pivot row with current rank row
        A[rank], A[pivot] = A[pivot], A[rank]
        
        # Eliminate
        for row in range(8):
            if row != rank and A[row][col] == 1:
                for c in range(col, N):
                    A[row][c] ^= A[rank][c]
        rank += 1
        
    # Now A has rank `rank` (should be 8).
    # The null space basis can be found by identifying free variables.
    # The pivot columns are those where a row has a leading 1.
    pivot_cols = []
    for i in range(rank):
        for j in range(N):
            if A[i][j] == 1:
                pivot_cols.append(j)
                break
                
    free_cols = [j for j in range(N) if j not in pivot_cols]
    
    # Basis for null space
    basis_95 = []
    for k, fc in enumerate(free_cols):
        vec = [0] * N
        vec[fc] = 1
        for i in range(rank):
            # The equation is x_pivot + sum(x_free) = 0
            # So x_pivot = sum(x_free)
            # We set x_fc = 1, others free = 0
            # So x_pivot = A[i][fc] (since other free vars are 0)
            # Wait, the row is: x_pivot_i + sum_{f in free} A[i][f] x_f = 0
            # So x_pivot_i = sum_{f in free} A[i][f] x_f
            vec[pivot_cols[i]] = A[i][fc]
        basis_95.append(vec)
        
    # Generate all 512 codewords of C_17,9,5
    codewords_95 = []
    for mask in range(1 << len(free_cols)):
        cw = [0] * N
        for i in range(len(free_cols)):
            if (mask >> i) & 1:
                for j in range(N):
                    cw[j] ^= basis_95[i][j]
        codewords_95.append(cw)
        
    # Filter for even weight to get C_17,8,6
    base_code = []
    for cw in codewords_95:
        if sum(cw) % 2 == 0:
            # Convert to int
            w = 0
            for i in range(N):
                if cw[i]:
                    w |= (1 << i)
            base_code.append(w)
            
    # 2. Initialize blocked array
    blocked = bytearray(1 << N)
    
    # Precompute masks for distances < MIN_DIST
    masks_by_dist = [[] for _ in range(MIN_DIST)]
    for d in range(MIN_DIST):
        for combo in combinations(range(N), d):
            mask = 0
            for i in combo:
                mask |= (1 << i)
            masks_by_dist[d].append(mask)
            
    def block_word(w):
        for d in range(MIN_DIST):
            for mask in masks_by_dist[d]:
                blocked[w ^ mask] = 1
                
    # Block all base codewords
    for w in base_code:
        block_word(w)
        
    # 3. Generate Candidates
    # Weight 8 and 9 vectors that are not blocked
    candidates = []
    for w in range(1 << N):
        if blocked[w]:
            continue
        pc = bin(w).count('1')
        if pc == 8 or pc == 9:
            candidates.append(w)
            
    # 4. Build Graph and Find Max Clique
    # Graph vertices are indices in candidates
    # Edge if distance >= 6
    
    # To speed up, we can use a greedy heuristic for Max Clique
    # Sort candidates by degree (descending)
    # Or just use a simple backtracking with pruning
    
    # Given time limits, a simple greedy might be faster and sufficient
    # Greedy: Pick vertex with highest degree, add to clique, remove neighbors, repeat.
    
    # Let's implement a simple greedy clique finder
    # 1. Compute degrees
    # 2. While candidates remain:
    #    a. Pick v with max degree
    #    b. Add v to clique
    #    c. Remove v and its neighbors from graph
    
    # However, computing the graph explicitly for ~20k nodes is O(N^2) = 400M ops.
    # This is too slow in Python.
    
    # Alternative:
    # We don't need the full graph.
    # We can use a greedy packing approach on the candidates?
    # No, the directive says "maximum clique problem... use a fast heuristic clique-finding algorithm".
    
    # Maybe the candidate set is smaller?
    # Base code blocks a lot.
    # Each base word blocks ~1 + 17 + 136 + 680 + 2380 + 6188 = 9402 words.
    # 256 words * 9402 / 2 (overlap) ?
    # The base code is a code with min distance 6.
    # The spheres of radius 5 around base codewords are disjoint?
    # Volume of sphere radius 5 in N=17:
    # C(17,0)+C(17,1)+C(17,2)+C(17,3)+C(17,4)+C(17,5)
    # 1 + 17 + 136 + 680 + 2380 + 6188 = 9402.
    # 256 * 9402 = 2,406,912.
    # Total words 131,072.
    # The spheres overlap heavily.
    # Actually, since min distance is 6, spheres of radius 2 are disjoint.
    # Spheres of radius 5 are NOT disjoint.
    # So the blocked set is not simply 256 * 9402.
    # But it covers a significant portion.
    
    # Let's check the size of candidates.
    # If candidates are ~5000, O(N^2) is 25M ops, which is fine.
    # If candidates are ~20000, O(N^2) is 400M ops, which is too slow.
    
    # We need a faster way to find a clique.
    # Or reduce candidates.
    
    # Let's try to estimate candidates.
    # The base code is linear.
    # The number of unblocked words is $2^{17} - | \cup B_w |$.
    # By Bonferroni, it's hard to estimate exactly.
    
    # Let's assume candidates are manageable.
    # We will use a greedy heuristic that doesn't build the full graph.
    # Greedy Clique:
    # 1. Start with empty clique C.
    # 2. While there are candidates:
    #    a. Find candidate v that is compatible with all in C.
    #    b. If found, add v to C.
    #    c. Remove from candidates any word incompatible with v.
    #    d. If no such v, break.
    
    # This is essentially greedy packing, but on the candidate set.
    # It finds a maximal clique, not necessarily maximum.
    # But it's fast.
    
    # To improve, we can sort candidates by weight or some heuristic.
    
    code = base_code[:]
    
    # Greedy extension
    # We want to add words to `code` such that they are compatible with all existing words.
    
    # We can iterate through candidates.
    # If candidate is compatible with all in `code`, add it.
    
    # To check compatibility with `code` (size ~256 + k), we check distance to all.
    # This is O(|code|) per candidate.
    # Total O(|cands| * |code|).
    # 20000 * 300 = 6M ops. Fast.
    
    # But this only finds a clique that is a subset of the greedy order.
    # It might miss better combinations.
    # But given the time limit, this is a safe bet.
    
    # Let's refine:
    # Sort candidates by weight (prefer 8 or 9).
    # Iterate.
    
    for w in candidates:
        if time.time() - start_time > time_limit:
            break
        # Check if w is compatible with all in code
        compatible = True
        for cw in code:
            if bin(w ^ cw).count('1') < MIN_DIST:
                compatible = False
                break
        if compatible:
            code.append(w)
            
    return code
